    const audioDB=new Promise(resolve=>{if(!root.indexedDB){resolve(null);return;}const request=indexedDB.open('word-explorer-recordings',1);request.onupgradeneeded=()=>request.result.createObjectStore('audio',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>resolve(null);request.onblocked=()=>resolve(null);});
    async function audioTransaction(mode,fn){const db=await audioDB;if(!db)throw new Error('此瀏覽器無法永久保存錄音；請使用原有下載錄音。');return new Promise((resolve,reject)=>{const tx=db.transaction('audio',mode);let value;const request=fn(tx.objectStore('audio'));if(request){request.onsuccess=()=>value=request.result;}tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
    function audioPlayer(r,label){const url=URL.createObjectURL(r.blob);audioUrls.push(url);return '<div><b>'+esc(label)+'</b><p class="ex-muted">'+esc(fmt(r.at))+' · '+(r.duration?Math.round(r.duration)+' 秒 · ':'')+Math.round(r.blob.size/1024)+' KB</p><audio aria-label="'+esc(label+' '+r.label)+'" controls preload="none" src="'+url+'"></audio><a href="'+url+'" download="'+esc(r.id)+'.'+(r.type.includes('mp4')?'m4a':r.type.includes('ogg')?'ogg':r.type.includes('wav')?'wav':'webm')+'">下載錄音</a></div>';}
    async function renderAudioLibrary(){const panel=document.getElementById('panel-speak');if(!panel)return;const seq=++audioRender;let rows,error='';try{rows=(await audioTransaction('readonly',s=>s.getAll())).sort((a,b)=>b.at-a.at);}catch(err){rows=[];error=err.message;}if(seq!==audioRender)return;const open=panel.querySelector('#ex-audio-library')?.open;audioUrls.forEach(u=>URL.revokeObjectURL(u));audioUrls=[];panel.querySelector('#ex-audio-library')?.remove();const section=document.createElement('details');section.id='ex-audio-library';section.className='ex-details';section.open=!!open;const groups=audioGroups(rows);section.innerHTML='<summary>🎙️ 我的錄音（'+rows.length+'）· 本機保存</summary><div><p class="ex-muted">錄音後按「保存到我的錄音」，填相同題目及模式就會自動分組，可對照首次與最新一次。聲音不包括在 JSON／Google 備份。</p>'+(error?'<p role="alert">'+esc(error)+'</p>':'')+(!rows.length?'<p>未有保存錄音。展開「本機錄音工具與評分說明」即可開始。</p>':'')+groups.map(group=>'<section class="ex-audio-group"><h3>'+esc(group[0].topic||group[0].label)+' · '+group.length+' 次</h3>'+(group.length>1?btn('首次／最新對照','compare-audio','data-id="'+esc(group[0].id)+'"'):'<p class="ex-muted">再錄同一題，即可對照重練。</p>')+group.slice().reverse().map((r,i)=>'<article class="ex-audio-row">'+audioPlayer(r,i===group.length-1?'第一次':i===0?'最新一次':'第 '+(group.length-i)+' 次')+'<p>'+esc(r.label)+'</p>'+(r.note?'<p>重練重點：'+esc(r.note)+'</p>':'')+btn('編輯題目與筆記','edit-audio','data-id="'+esc(r.id)+'"')+' '+btn('移除此錄音','delete-audio','data-id="'+esc(r.id)+'"')+'</article>').join('')+'</section>').join('')+'</div>';panel.append(section);}
    function audioForm(r){return '<label>題目（同題請填相同文字）<input name="topic" required maxlength="300" value="'+esc(r.topic||r.label||'')+'" placeholder="例如：How can cities be made greener?"></label><label>模式<input name="mode" maxlength="60" value="'+esc(r.mode||settings().lastMode||'free')+'"></label><label>錄音名稱<input name="label" maxlength="120" value="'+esc(r.label||'')+'" placeholder="例如：重練 · 加入例子"></label><label>下一次重練重點<textarea name="note" maxlength="2000" placeholder="例如：減少停頓、加入具體例子">'+esc(r.note||'')+'</textarea></label>';}
